record.field:
readings = env['x_meter_reading'].search_fetch([('id', 'in', record.x_property.x_meter_reading_ids.ids), ('x_meter_id', '=', record.x_meter_id.id)], ['x_quantity'], order='x_date')
for i in range(len(readings)):
    readings[i]['x_usage'] = readings[i].x_quantity - readings[i-1].x_quantity if i else 0

for line in record:
    if line.x_end_date and line.x_end_date < line.x_start_date: raise UserError("End Date must be empty or after Start Date.")
    domain = [('id', '!=', line.id), ('x_property_id', '=', line.x_property_id.id), ('x_type', '=', line.x_type), ('x_start_date', '!=', False), '|', ('x_end_date', '=', False), ('x_end_date', '>=', line.x_start_date)]
    if line.x_end_date: domain.append(('x_start_date', '<=', line.x_end_date))
    if env['x_stake_holder'].search_count(domain, limit=1): raise UserError("Stakeholder dates cannot overlap for the same property. Ensure that periods do not overlap.")

plan = env['account.analytic.plan'].search([('x_is_a_property_plan', '=', True)], limit=1) or env['account.analytic.plan'].create({'name': 'Accounts', 'x_is_a_property_plan': True})
for line in records:
    if (partner := line.x_stake_holder) and not env['account.analytic.account'].search_count([('x_property', '=', line.x_property_id.id), ('partner_id', '=', partner.id), ('x_type', '=', line.x_type)]):
        line['x_account'] = env['account.analytic.account'].create({
            'name': line.x_property_id.x_name,
            'plan_id': plan.id,
            'x_property': line.x_property_id.id,
            'partner_id': partner.id,
            'x_stake_holder_line': line.id,
            'company_id': line.x_property_id.x_company_id.id,
            'x_type': line.x_type,
        }).id

def findClosestMeterReading(meter_readings, date):
    # return the closest meter reading to the given date.
    # if no date is given, assume it is infinitely large to find the latest reading.
    date = date or datetime.date.max
    closest_mr, cur_diff = False, float('inf')
    for mr in meter_readings:
        diff = abs((date - mr.x_date).days)
        if diff< cur_diff: closest_mr, cur_diff = mr, diff
    return closest_mr

for record in (records or []):
    analytic_distribution = {}
    if (dist_key := record.x_distribution_key):
        period_start, period_end = record.x_period_start, record.x_period_end or datetime.date.today()
        # Share distribution
        if dist_key.x_based_on == "Shares" and period_start:
            for ratio in dist_key.x_ratio_ids:
                if not ratio.x_ratio: continue
                for account in ratio.x_property_ratios.x_account_ids:
                    acc_start, acc_end = account.x_start_date, account.x_end_date
                    if acc_start <= period_end and (not acc_end or period_start <= acc_end):
                        overlap_start, overlap_end = max(acc_start, period_start), min(acc_end or period_end, period_end)
                        analytic_distribution[account.id] = analytic_distribution.get(account.id, 0) + ((overlap_end - overlap_start).days + 1) * ratio.x_ratio
        # Meter distribution
        elif dist_key.x_based_on == "Meter Readings" and period_start:
            for property in record.invoice_line_ids.x_property_id or env['x_property'].search([('x_company_id', '=', dist_key.x_company_id.id)]):
                readings = property.x_meter_reading_ids.filtered(lambda mr: mr.x_meter_id.id == dist_key.x_meter.id)
                if len(readings) < 2: continue
                for account in property.x_account_ids:
                    acc_start, acc_end = account.x_start_date, account.x_end_date
                    if not acc_start or acc_start > period_end or (acc_end and acc_end <= period_start): continue
                    mrostart = findClosestMeterReading(readings, acc_start)
                    mroend = findClosestMeterReading(readings, acc_end)
                    if mrostart.x_date < mroend.x_date:
                        analytic_distribution[account.id] = abs(mroend.x_quantity - mrostart.x_quantity)
        # Outcome
        if (total_ratio := sum(analytic_distribution.values())):
            for key in analytic_distribution: analytic_distribution[key] *= 100 / total_ratio
        record.invoice_line_ids.write({'analytic_distribution': analytic_distribution})
